#include "ShaderCodeGenerator.h"

#include "Core/CoreTypes.h"

#include <cstddef>
#include <format>
#include <string_view>

namespace
{
	/** How many SPIR-V words are written on a line of the generated file. */
	constexpr std::size_t WordsPerLine = 8;

	/** Returns Text as it must be written between the quotes of a C++ string literal. */
	std::string EscapeForStringLiteral(std::string_view Text)
	{
		std::string Escaped;
		Escaped.reserve(Text.size());
		for (const char Character : Text)
		{
			if (Character == '"' || Character == '\\')
			{
				Escaped += '\\';
			}
			Escaped += Character;
		}

		return Escaped;
	}

	void AppendCodeArray(std::string& Text, std::size_t ShaderIndex, std::span<const uint32> Code)
	{
		Text += std::format("\tconstexpr uint32 ShaderCode{}[] = {{", ShaderIndex);
		for (std::size_t WordIndex = 0; WordIndex < Code.size(); ++WordIndex)
		{
			const bool bStartsLine = WordIndex % WordsPerLine == 0;
			Text += bStartsLine ? "\n\t\t" : " ";
			Text += std::format("0x{:08x},", Code[WordIndex]);
		}
		Text += "\n\t};\n\n";
	}
}

std::string FShaderCodeGenerator::Generate(std::span<const FCompiledShader> Shaders)
{
	std::string Text = "// Generated by WhiteWolfShaderCompiler. Do not edit: changes are lost on the next build.\n"
					   "#include \"Rendering/ShaderLibrary.h\"\n"
					   "\n";

	if (Shaders.empty())
	{
		Text += "std::span<const FEmbeddedShader> FShaderLibrary::GetEmbeddedShaders()\n"
				"{\n"
				"\treturn {};\n"
				"}\n";
		return Text;
	}

	Text += "namespace\n"
			"{\n";
	for (std::size_t ShaderIndex = 0; ShaderIndex < Shaders.size(); ++ShaderIndex)
	{
		AppendCodeArray(Text, ShaderIndex, Shaders[ShaderIndex].Code);
	}

	Text += "\tconstexpr FEmbeddedShader EmbeddedShaders[] = {\n";
	for (std::size_t ShaderIndex = 0; ShaderIndex < Shaders.size(); ++ShaderIndex)
	{
		Text += std::format(
			"\t\t{{\"{}\", ShaderCode{}}},\n", EscapeForStringLiteral(Shaders[ShaderIndex].Name), ShaderIndex);
	}
	Text += "\t};\n"
			"}\n"
			"\n"
			"std::span<const FEmbeddedShader> FShaderLibrary::GetEmbeddedShaders()\n"
			"{\n"
			"\treturn EmbeddedShaders;\n"
			"}\n";
	return Text;
}
